cd /tmp; timeout 300 nix-instantiate --eval --strict --impure -E '
let pkgs = import /opt/nixpkgs { config = {}; overlays = []; }; in {
  httpd = pkgs.apacheHttpd.version;
  wsgi = pkgs.apacheHttpdPackages.mod_wsgi.name or "none";
  php81 = pkgs.php81.version or "none";
  php = pkgs.php.version;
  pg14 = pkgs.postgresql_14.version;
  postgis = (pkgs.postgresql_14.pkgs.postgis.name) or "none";
  mariadb = pkgs.mariadb.version;
  memcached = pkgs.memcached.version;
  requests = pkgs.python3Packages.requests.version;
}' 2>&1 | tail -20

