        group = "cobalt";
        listen = "/run/php/php-cobalt-fpm.sock";
        phpEnv = {
          HOME = "/home/cobalt";
          PATH = "/usr/local/bin:/usr/bin:/bin";
          TMP = "/tmp";
          TMPDIR = "/tmp";
          NODE_LABEL = "cobalt";
        };
        settings = {
          "listen.owner" = "www-data";
          "listen.group" = "www-data";
          "listen.mode" = "0660";
          "pm" = "dynamic";
          "pm.max_children" = 10;
          "pm.start_servers" = 2;
          "pm.min_spare_servers" = 1;
          "pm.max_spare_servers" = 3;
          "pm.max_requests" = 10000;
          "request_terminate_timeout" = 180;
          "clear_env" = "yes";
          "php_value[max_execution_time]" = 120;
          "php_value[memory_limit]" = "128M";
          "php_value[post_max_size]" = "8M";
          "php_value[upload_max_filesize]" = "8M";
          "php_admin_value[open_basedir]" = "/home/cobalt/:/tmp/:/usr/share/php/";
          "php_flag[display_errors]" = "off";
        };
      };
    };
  };
  # Pools must be able to read their tenant's home directory.
  systemd.services.phpfpm-amber.serviceConfig.ProtectHome = lib.mkForce false;
  systemd.services.phpfpm-cobalt.serviceConfig.ProtectHome = lib.mkForce false;

  # ---- MariaDB ----------------------------------------------------------
  services.mysql = {
    enable = true;
    package = pkgs.mariadb;
    settings.mysqld = {
      bind-address = "127.0.0.1";
      character-set-server = "utf8mb4";
      collation-server = "utf8mb4_general_ci";
    };
    initialScript = mysqlInit;
  };

  # ---- PostgreSQL -------------------------------------------------------
  services.postgresql = {
    enable = true;
    package = pkgs.postgresql_14;
    extensions = ps: [ ps.postgis ];
    initdbArgs = [ "--encoding=UTF8" "--locale=C.UTF-8" ];
    enableTCPIP = true;
    authentication = lib.mkForce ''
      local all all peer
      host all all 127.0.0.1/32 scram-sha-256
      host all all ::1/128 scram-sha-256
    '';
    initialScript = pgInit;
  };

  # ---- memcached --------------------------------------------------------
  services.memcached = {
    enable = true;
    user = "memcache";
    listen = "127.0.0.1";
    port = 11211;
    maxMemory = 32;
    extraOptions = [ "-U" "0" ];
  };

  # ---- Packages on the default PATH -------------------------------------
  environment.systemPackages = [
    php
    python
    pkgs.mariadb
    pkgs.postgresql_14
    pkgs.netcat-openbsd
    pkgs.socat
    pkgs.openssl
  ];
}

